USE `if0_43266899_FurryHomes`;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY, name TEXT NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('Admin','Staff','Adopter')), phone TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS pets(id INT AUTO_INCREMENT PRIMARY KEY, name TEXT NOT NULL, species TEXT NOT NULL, breed TEXT NOT NULL, age TEXT NOT NULL, gender TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Available' CHECK(status IN ('Available','In foster','Adopted','On hold')), description TEXT NOT NULL DEFAULT '', photo TEXT, intake_date TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS applications(id INT AUTO_INCREMENT PRIMARY KEY, pet_id INT NOT NULL, user_id INT NOT NULL, housing TEXT NOT NULL, experience TEXT NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Approved','Rejected')), notes TEXT NOT NULL DEFAULT '', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE(pet_id,user_id), FOREIGN KEY (pet_id) REFERENCES pets(id), FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS medical(id INT AUTO_INCREMENT PRIMARY KEY, pet_id INT NOT NULL, kind TEXT NOT NULL, record_date TEXT NOT NULL, details TEXT NOT NULL, next_due TEXT, created_by INT, FOREIGN KEY (pet_id) REFERENCES pets(id), FOREIGN KEY (created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS contacts(id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, note TEXT NOT NULL, created_by INT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS contracts(id INT AUTO_INCREMENT PRIMARY KEY, application_id INT NOT NULL UNIQUE, fee DECIMAL(10,2) NOT NULL CHECK(fee>=0), payment TEXT NOT NULL CHECK(payment IN ('Unpaid','Paid','Waived')), agreement TEXT NOT NULL, ownership_document TEXT NOT NULL, signed_date TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (application_id) REFERENCES applications(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS fosters(id INT AUTO_INCREMENT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL, address TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS placements(id INT AUTO_INCREMENT PRIMARY KEY, pet_id INT NOT NULL, foster_id INT NOT NULL, start_date TEXT NOT NULL, end_date TEXT, active_pet_id INT GENERATED ALWAYS AS (CASE WHEN end_date IS NULL THEN pet_id ELSE NULL END) STORED, UNIQUE KEY one_active_foster(active_pet_id), FOREIGN KEY (pet_id) REFERENCES pets(id), FOREIGN KEY (foster_id) REFERENCES fosters(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS notifications(id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, message TEXT NOT NULL, seen INT NOT NULL DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS audit(id INT AUTO_INCREMENT PRIMARY KEY, user_id INT, action TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS login_attempts(id INT AUTO_INCREMENT PRIMARY KEY, email TEXT NOT NULL, ip TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


